const dialog = document.getElementById('game-dialog');
const dialogBody = document.getElementById('dialog-body');
const screen = document.querySelector('[data-screen]').dataset.screen;
let opener, toastTimer;
let activeWorld = 0, activeCharacter = 0, growthStage = 0;
const levels = [
  {name:'Just One Small Feature',description:'Build the Product. Defend it from Problems.',status:'RUN IN PROGRESS'},
  {name:'Scope Creep',description:'One more request. And another. A future level about an ever-growing scope.',status:'FUTURE LEVEL CONCEPT'},
  {name:'Release Friday',description:'The release is close. The weekend is closer. A future level theme.',status:'FUTURE LEVEL CONCEPT'}
];
const characters = [
  {name:'Developer',color:'#28aaa4',type:'dev',role:'The throughput specialist.',traits:['Completes Work faster','Resolves Problems faster'],description:'More direct throughput for both Work and Problems. Specialize a placed Base Copilot during a level.',unlock:'Available from the start.'},
  {name:'Tester',color:'#cfaa5e',type:'tester',role:'Better together.',traits:['Quality Aura slows Problems','Nearby completed Work earns bonus Compute'],description:'Works and defends while a Quality Aura improves nearby outcomes. Aura effects do not stack.',unlock:'Available from the start.'},
  {name:'Analyst',color:'#9697b8',type:'dev',role:'Clarity starts upstream.',traits:['Requirement clarity','Upstream prevention'],description:'A future specialist focused on reducing ambiguity before it becomes missed Work and Technical Debt.',unlock:'Complete Level 01 to unlock permanently.'},
  {name:'Security',color:'#819da9',type:'tester',role:'Eyes on the unexpected.',traits:['Hidden threat detection','Security specialization'],description:'A future specialist for hidden or high-severity security threats.',unlock:'Unlock through a later milestone. Details to be designed.'}
];
function setDialog(label,body){if(!dialog.open)opener=document.activeElement;document.getElementById('dialog-title').textContent=label;dialogBody.innerHTML=body;if(!dialog.open)dialog.showModal();dialog.scrollTop=0;document.getElementById('dialog-close').focus()}
function closeDialog(){dialog.close();if(opener?.isConnected)opener.focus()}
function notify(message){clearTimeout(toastTimer);const t=document.getElementById('toast');t.textContent=message;toastTimer=setTimeout(()=>t.textContent='',3500)}
function openLevels(){setDialog('SELECT LEVEL',levels.map((l,i)=>'<button class="level-choice" data-mission="'+i+'"><strong>0'+(i+1)+'</strong><span><h3>'+l.name+'</h3><small>'+l.status+'</small></span>'+icon(i===0?'play':'lock')+'</button>').join(''))}
function openBriefing(resume=true,world=0){
  if(world>0){setDialog(levels[world].name,'<div class="brief-grid"><div class="brief-art locked-art">'+campus('future-'+world)+'</div><div class="brief-copy"><span class="status-tag">'+icon('lock')+' FUTURE LEVEL</span><h3>More stories ahead.</h3><p style="font-size:13px;line-height:1.6">'+levels[world].description+'</p></div></div><div class="dialog-actions"><button class="game-button" data-action="missions">ALL LEVELS</button><button class="game-button primary" data-action="continue">'+icon('play')+' LEVEL 01</button></div><p class="overlay-note">Theme preview. Its waves, boss, and unlock conditions are still to be designed.</p>');return}
  setDialog(resume?'CONTINUE RUN':'LEVEL 01','<div class="brief-grid"><div class="brief-art">'+campus('briefing')+'</div><div class="brief-copy"><span class="status-tag">'+icon('play')+' '+(resume?'SAVED BETWEEN WAVES':'READY TO BUILD')+'</span><h3>Just One<br>Small Feature</h3><div class="mini-status">'+icon('missions')+' '+(resume?'Round 4 · Planning':'Round 1 · Planning')+'</div><div class="mini-status">'+icon('team')+' Developer + Tester available</div><div class="mini-status">'+icon('lock')+' Finish the level → Unlock Analyst</div></div></div><div class="dialog-actions"><button class="game-button" data-action="close">BACK</button><button class="game-button primary" data-planning="'+(resume?'resume':'new')+'">'+icon('play')+' ENTER PLANNING</button></div><p class="overlay-note center">UI prototype · Sample run. Opens a planning preview.</p>');
}
function openPlanning(resume){setDialog('PLAN YOUR NEXT MOVE','<div class="planning-stage"><div class="planning-hud"><span class="status-tag">ROUND '+(resume?'4':'1')+' / ~8</span><span class="status-tag">PLANNING</span></div>'+campus('plan')+'<span class="planning-unit" aria-hidden="true"></span></div><div class="mode-panel"><h3>DEVELOPER</h3><button class="game-button" data-mode="Build" aria-pressed="false">BUILD</button><button class="game-button" data-mode="Defend" aria-pressed="false">DEFEND</button><button class="game-button selected" data-mode="Auto" aria-pressed="true">AUTO</button></div><p class="mode-help" id="mode-help">Auto: handles visible Problems before visible Work.</p><div class="dialog-actions"><button class="game-button primary" data-action="close">'+icon('home')+' BACK TO HUB</button></div><p class="overlay-note center">Planning UI preview · Gameplay is not connected.</p>')}
function openTeam(){setDialog('YOUR COPILOTS','<div class="collection">'+characters.map((c,i)=>'<button data-persona="'+i+'"><div class="'+(i>1?'locked-art':'')+'">'+bot(c.color,c.type)+'</div><h3>'+c.name.toUpperCase()+'</h3><p>'+(i<2?'AVAILABLE':i===2?'FINISH LEVEL 01':'LATER MILESTONE')+'</p></button>').join('')+'</div><p class="overlay-note center">Place a Base Copilot. Specialize during the level.</p>')}
function openPersona(index){const c=characters[index];setDialog(c.name,'<div class="persona-detail"><div class="'+(index>1?'locked-art':'')+'">'+bot(c.color,c.type)+'</div><div><span class="status-tag">'+icon(index<2?'check':'lock')+' '+(index<2?'AVAILABLE':'LOCKED')+'</span><h3>'+c.role+'</h3><p>'+c.description+'</p><div class="trait-list">'+c.traits.map(t=>'<span>'+icon('check')+t+'</span>').join('')+'</div><p style="margin-top:20px;font-weight:800;font-size:11px">'+c.unlock+'</p></div></div><div class="dialog-actions"><button class="game-button" data-action="team">ALL COPILOTS</button><button class="game-button primary" data-action="close">DONE</button></div>')}
function openProduct(stage=0){growthStage=stage;const stages=['A SMALL BEGINNING','ROOM TO GROW','SOMETHING WORTH PROTECTING'];setDialog('YOUR PRODUCT','<div class="growth-view" id="growth-view">'+campus('growth')+'</div><h3 class="growth-title">'+stages[stage]+'</h3><div class="growth-controls" aria-label="Growth preview">'+stages.map((s,i)=>'<button class="game-button '+(i===stage?'selected':'')+'" data-growth="'+i+'" aria-pressed="'+(i===stage)+'" aria-label="'+s+'">0'+(i+1)+'</button>').join('')+'</div><p class="overlay-note center">Visual growth preview · Completed Work grows your Product after successful levels.<br>Growth grants no combat-stat bonus.</p>');document.querySelector('#growth-view .product-building').style.transform='scale('+(0.78+stage*.21)+')'}
function openSettings(){setDialog('SETTINGS','<label class="setting-row"><span><strong>Reduce motion</strong><p>Keep the world and Copilots still.</p></span><input id="motion-setting" type="checkbox" '+(document.body.classList.contains('reduced-motion')?'checked':'')+'></label><label class="setting-row"><span><strong>Higher contrast</strong><p>Strengthen text and control borders.</p></span><input id="contrast-setting" type="checkbox" '+(document.body.classList.contains('high-contrast')?'checked':'')+'></label><div class="dialog-actions"><button class="game-button" data-action="help">HOW TO PLAY</button><button class="game-button primary" data-action="close">DONE</button></div><p class="overlay-note center">Preferences saved separately for this prototype.</p>')}
function openHelp(){setDialog('BUILD. DEFEND. REPEAT.','<div class="trait-list" style="font-size:14px;gap:23px"><span>'+icon('product')+' Complete Work to earn Compute and grow the Product.</span><span>'+icon('team')+' Specialize Copilots as Developers or Testers.</span><span>'+icon('missions')+' Plan between waves. Start when you are ready.</span><span>'+icon('lock')+' Defeat the Production Incident to unlock the Analyst.</span></div><p class="overlay-note">Unfinished Work adds Technical Debt. Clean it up before the final encounter.</p><div class="dialog-actions"><button class="game-button primary" data-action="continue">'+icon('play')+' CONTINUE</button></div>')}
function selectWorld(index){activeWorld=(index+levels.length)%levels.length;document.querySelectorAll('[data-world]').forEach(b=>{const chosen=+b.dataset.world===activeWorld;b.classList.toggle('active',chosen);b.setAttribute('aria-pressed',String(chosen))});document.getElementById('level-number').textContent='0'+(activeWorld+1);document.getElementById('level-status').textContent='LEVEL 0'+(activeWorld+1)+' · '+levels[activeWorld].status;document.getElementById('level-title').textContent=levels[activeWorld].name;document.getElementById('level-subtitle').textContent=activeWorld===0?'Round 4 · Final encounter: Production Incident':'Theme preview · Not playable yet';const launch=document.getElementById('map-launch');launch.innerHTML=icon(activeWorld===0?'play':'lock')+(activeWorld===0?' CONTINUE':' PREVIEW');launch.dataset.action=activeWorld===0?'continue':'world-preview';document.querySelector('.reward-preview').style.visibility=activeWorld===0?'visible':'hidden'}
function selectCharacter(index){activeCharacter=(index+characters.length)%characters.length;const c=characters[activeCharacter];document.querySelectorAll('[data-character]').forEach(b=>{const chosen=+b.dataset.character===activeCharacter;b.classList.toggle('active',chosen);b.setAttribute('aria-pressed',String(chosen))});document.getElementById('character-name').textContent=c.name;document.getElementById('character-role').textContent=c.role;document.getElementById('character-status').innerHTML=icon(activeCharacter<2?'check':'lock')+' '+(activeCharacter<2?'PERSONA AVAILABLE':activeCharacter===2?'FINISH LEVEL 01':'LATER MILESTONE');document.getElementById('trait-one').innerHTML=icon('check')+' '+c.traits[0];document.getElementById('trait-two').innerHTML=icon('check')+' '+c.traits[1];document.getElementById('character-hero').innerHTML=bot(c.color,c.type);document.getElementById('character-hero').classList.toggle('locked',activeCharacter>1);document.getElementById('character-hero').setAttribute('aria-label',c.name+' Copilot'+(activeCharacter>1?', locked':''));document.getElementById('bay-number').innerHTML='0'+(activeCharacter+1)+'<small>PERSONA SHOWCASE</small>'}
async function toggleFullscreen(){try{if(document.fullscreenElement)await document.exitFullscreen();else await document.documentElement.requestFullscreen()}catch{notify('Fullscreen is unavailable in this browser panel.')}}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.world!==undefined){selectWorld(+b.dataset.world);return}if(b.dataset.character!==undefined){selectCharacter(+b.dataset.character);return}if(b.dataset.persona!==undefined){openPersona(+b.dataset.persona);return}if(b.dataset.mission!==undefined){openBriefing(false,+b.dataset.mission);return}if(b.dataset.planning){openPlanning(b.dataset.planning==='resume');return}if(b.dataset.growth!==undefined){const stage=+b.dataset.growth;openProduct(stage);document.querySelector('[data-growth="'+stage+'"]').focus();return}if(b.dataset.mode){document.querySelectorAll('[data-mode]').forEach(c=>{c.classList.toggle('selected',c===b);c.setAttribute('aria-pressed',String(c===b))});document.getElementById('mode-help').textContent={Build:'Build: completes productive Work and cleanup. Ignores Problems.',Defend:'Defend: resolves Problems. Ignores Work and cleanup.',Auto:'Auto: handles visible Problems before visible Work.'}[b.dataset.mode];return}({continue:()=>openBriefing(),missions:openLevels,team:openTeam,product:()=>openProduct(growthStage),settings:openSettings,help:openHelp,close:closeDialog,fullscreen:toggleFullscreen,'world-preview':()=>openBriefing(false,activeWorld),'next-world':()=>selectWorld(activeWorld+1),'next-character':()=>selectCharacter(activeCharacter+1),'previous-character':()=>selectCharacter(activeCharacter-1),'character-detail':()=>openPersona(activeCharacter)})[b.dataset.action]?.()});
document.addEventListener('keydown',e=>{if(dialog.open||e.ctrlKey||e.metaKey||e.altKey)return;if(e.key==='ArrowLeft'||e.key==='ArrowRight'){if(screen==='map'){e.preventDefault();selectWorld(activeWorld+(e.key==='ArrowRight'?1:-1))}if(screen==='hangar'){e.preventDefault();selectCharacter(activeCharacter+(e.key==='ArrowRight'?1:-1))}}if(e.key==='Enter'&&document.activeElement===document.body){e.preventDefault();openBriefing(true,screen==='map'?activeWorld:0)}});
const preferencesKey='tower-hub-v02-'+screen+'-preferences';
try{const p=JSON.parse(localStorage.getItem(preferencesKey)||'{}');document.body.classList.toggle('reduced-motion',!!p.motion);document.body.classList.toggle('high-contrast',!!p.contrast)}catch{}
document.addEventListener('change',e=>{if(!['motion-setting','contrast-setting'].includes(e.target.id))return;document.body.classList.toggle(e.target.id==='motion-setting'?'reduced-motion':'high-contrast',e.target.checked);try{localStorage.setItem(preferencesKey,JSON.stringify({motion:document.body.classList.contains('reduced-motion'),contrast:document.body.classList.contains('high-contrast')}))}catch{notify('Preference applied for this visit. Storage is unavailable.')}});
dialog.addEventListener('cancel',e=>{e.preventDefault();closeDialog()});
dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeDialog()}});
